import{_ as r}from"./chunks/show_rankings.jyDr3-70.js";import{_ as t,H as n,c as i,b as s,a0 as a,K as l}from"./chunks/framework.DZ_FiXNr.js";const w=JSON.parse('{"title":"Show Rankings","description":"Show Rankings lets you monitor how your podcast ranks for specific keywords across Apple Podcasts, Spotify, Amazon Music, and YouTube Music. Review tracked keywords across platforms, organize them into groups, and inspect their history. Use Strategy to add or assign terms.","frontmatter":{},"headers":[],"relativePath":"features/show-rankings.md","filePath":"features/show-rankings.md"}'),h={name:"features/show-rankings.md"};function d(g,e,c,u,p,m){const o=n("HelpWalkthrough");return s(),i("div",null,[e[0]||(e[0]=a('<h1 id="show-rankings" tabindex="-1">Show Rankings <a class="header-anchor" href="#show-rankings" aria-label="Permalink to &quot;Show Rankings&quot;">​</a></h1><h2 id="track-your-keyword-rankings-across-all-platforms" tabindex="-1">Track Your Keyword Rankings Across All Platforms <a class="header-anchor" href="#track-your-keyword-rankings-across-all-platforms" aria-label="Permalink to &quot;Track Your Keyword Rankings Across All Platforms&quot;">​</a></h2><p>Show Rankings lets you monitor how your podcast ranks for specific keywords across Apple Podcasts, Spotify, Amazon Music, and YouTube Music. Review tracked keywords across platforms, organize them into groups, and inspect their history. Use Strategy to add or assign terms.</p><p><strong>To access:</strong> <strong>Search Visibility → Rankings → Show</strong>. Show and Episodes are modes of the single <a href="/features/rankings.html">Rankings tab</a>. Older links called this Show Rankings or Platform Rankings.</p><p><a href="/images/show_rankings.webp" title="Open screenshot at full size"><img src="'+r+'" alt="Show Rankings Dashboard" width="600px" style="display:block;margin:0 auto;"></a></p><h2 id="what-you-ll-see" tabindex="-1">What You&#39;ll See <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;What You&#39;ll See&quot;">​</a></h2><h3 id="multi-platform-ranking-table" tabindex="-1">Multi-Platform Ranking Table <a class="header-anchor" href="#multi-platform-ranking-table" aria-label="Permalink to &quot;Multi-Platform Ranking Table&quot;">​</a></h3><p>The main view shows your tracked keywords with rankings for each platform:</p><ul><li><strong>Keyword</strong> - The search term you&#39;re tracking</li><li><strong>Groups</strong> - The themes the keyword belongs to, shown read-only; manage memberships in Strategy</li><li><strong>Apple Podcasts (AP)</strong> - Current rank and change indicator</li><li><strong>Spotify (SP)</strong> - Current rank and change indicator</li><li><strong>Amazon Music (AM)</strong> - Current rank and change indicator</li><li><strong>YouTube Music (YM)</strong> - Current rank and change indicator</li></ul><p>Each platform column shows:</p><ul><li>Your current position (e.g., #8)</li><li>An arrow showing whether the position improved or fell over the selected comparison period, when an earlier position is available</li><li>Blank if not ranking for that keyword</li></ul><h3 id="ranking-chart" tabindex="-1">Ranking Chart <a class="header-anchor" href="#ranking-chart" aria-label="Permalink to &quot;Ranking Chart&quot;">​</a></h3><p>Above the table, a line chart shows the ranking history of one keyword at a time. Select a keyword in the table and the chart plots its position on all four platforms—Apple Podcasts, Spotify, Amazon Music, and YouTube Music—as separate lines over your chosen timeframe, so you can compare platforms side by side.</p><h3 id="smart-groups" tabindex="-1">Smart Groups <a class="header-anchor" href="#smart-groups" aria-label="Permalink to &quot;Smart Groups&quot;">​</a></h3><p>Quick filters to find keywords by performance:</p><ul><li><strong>All Keywords</strong> - Your complete tracking list</li><li><strong>Top 10</strong> - Keywords where you rank in the top 10</li><li><strong>Rising</strong> - Keywords with improving rankings</li><li><strong>Dropping</strong> - Keywords losing positions</li><li><strong>New (7 days)</strong> - Recently added keywords</li><li><strong>Not Ranking</strong> - Keywords where you don&#39;t appear in results</li></ul><h3 id="custom-groups" tabindex="-1">Custom Groups <a class="header-anchor" href="#custom-groups" aria-label="Permalink to &quot;Custom Groups&quot;">​</a></h3><p>The <strong>Groups</strong> column displays your existing themes with their colors. Group membership is read-only in Rankings; use <strong>Manage keywords in Strategy</strong> to create themes or change assignments.</p><h2 id="managing-your-keywords" tabindex="-1">Managing Your Keywords <a class="header-anchor" href="#managing-your-keywords" aria-label="Permalink to &quot;Managing Your Keywords&quot;">​</a></h2><h3 id="adding-keywords" tabindex="-1">Adding Keywords <a class="header-anchor" href="#adding-keywords" aria-label="Permalink to &quot;Adding Keywords&quot;">​</a></h3><p>Click <strong>Manage keywords in Strategy</strong> to add or assign keywords. Consider tracking:</p><ul><li>Your show keywords (the core topics of your positioning)</li><li>Competitor keywords you want to rank for</li><li>Topic keywords in your niche</li><li>Branded terms (your podcast name, host names)</li></ul><h3 id="manage-groups-in-strategy" tabindex="-1">Manage Groups in Strategy <a class="header-anchor" href="#manage-groups-in-strategy" aria-label="Permalink to &quot;Manage Groups in Strategy&quot;">​</a></h3><ol><li>Click <strong>Manage keywords in Strategy</strong>.</li><li>Use the keyword&#39;s <strong>Themes</strong> control or <strong>Assign → Theme</strong> to organize it.</li><li>Return to <strong>Rankings → Show</strong> to review the updated Groups column.</li></ol><p>A keyword can belong to more than one theme. Changing a theme does not create another tracked keyword.</p><h3 id="compare-the-same-keyword-over-time" tabindex="-1">Compare the same keyword over time <a class="header-anchor" href="#compare-the-same-keyword-over-time" aria-label="Permalink to &quot;Compare the same keyword over time&quot;">​</a></h3><ol><li>Select a keyword to draw its history across the four platforms.</li><li>Start with <strong>15 days</strong>, then choose <strong>90 days</strong> for a longer view.</li><li>Read the same row&#39;s change indicators alongside the chart. The comparison period changes; the keyword stays the same.</li></ol>',27)),l(o,{src:"/walkthroughs/rankings-period.webp",poster:"/images/show_rankings.webp",alt:"Select one keyword and compare its ranking chart and position changes over 15 and 90 days",duration:20400,autoplay:"",loop:"",sample:""}),e[1]||(e[1]=a('<p>An earlier position must be available to calculate a change. A dash or a missing comparison is not a download count.</p><h3 id="exporting-data" tabindex="-1">Exporting Data <a class="header-anchor" href="#exporting-data" aria-label="Permalink to &quot;Exporting Data&quot;">​</a></h3><p>Click <strong>Download CSV</strong> to export your keyword data for external analysis or reporting.</p><h3 id="over-your-keyword-limit" tabindex="-1">Over Your Keyword Limit <a class="header-anchor" href="#over-your-keyword-limit" aria-label="Permalink to &quot;Over Your Keyword Limit&quot;">​</a></h3><p>If you&#39;re tracking more keywords than your plan allows (for example, after changing plans), a warning appears above the table: &quot;You&#39;re tracking more keywords than your plan allows.&quot; Upgrade to raise your keyword limit and get complete data, or remove keywords you no longer need.</p><h2 id="understanding-your-rankings" tabindex="-1">Understanding Your Rankings <a class="header-anchor" href="#understanding-your-rankings" aria-label="Permalink to &quot;Understanding Your Rankings&quot;">​</a></h2><h3 id="reading-the-change-indicators" tabindex="-1">Reading the change indicators <a class="header-anchor" href="#reading-the-change-indicators" aria-label="Permalink to &quot;Reading the change indicators&quot;">​</a></h3><p>The change indicator compares the latest position with an earlier position for the selected comparison period:</p><ul><li><strong>Up arrow</strong> - Ranking improved (moved up)</li><li><strong>Down arrow</strong> - Ranking dropped (moved down)</li><li><strong>No arrow</strong> - Position unchanged, or no comparable earlier position is available</li></ul><h3 id="platform-differences" tabindex="-1">Platform Differences <a class="header-anchor" href="#platform-differences" aria-label="Permalink to &quot;Platform Differences&quot;">​</a></h3><p>Rankings often vary by platform:</p><ul><li>A keyword ranking #5 on Apple might be #15 on Spotify</li><li>Some platforms may not rank your podcast for certain keywords</li><li>Focus optimization where you have the most potential</li></ul><h3 id="country-differences" tabindex="-1">Country Differences <a class="header-anchor" href="#country-differences" aria-label="Permalink to &quot;Country Differences&quot;">​</a></h3><p>The Show Rankings table shows positions as a listener in the United States sees them. A keyword can rank very differently in other markets; to compare countries, add search countries for the podcast in <strong>Settings → Shows</strong> (paid plans, with a per-podcast allowance of additional countries) and use the country selector in <a href="/features/keyword-tracker.html#search-countries">Keyword Tracker</a> — that&#39;s where per-country rankings are shown. Adding countries doesn&#39;t change this table.</p><h2 id="choose-your-next-action" tabindex="-1">Choose your next action <a class="header-anchor" href="#choose-your-next-action" aria-label="Permalink to &quot;Choose your next action&quot;">​</a></h2><p>Use <strong>Dropping</strong> to find terms worth investigating and <strong>Top 10</strong> to review established positions. Compare related metadata edits with ranking history, while remembering that timing alone does not prove what caused a change. Manage targets in <strong>Strategy</strong>, and use <strong>Tracker</strong> for country comparisons and competitor history.</p><h2 id="integration-with-other-features" tabindex="-1">Integration with Other Features <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;Integration with Other Features&quot;">​</a></h2><ul><li><strong>Keyword Strategy</strong> - Keywords from your strategy appear here</li><li><strong>Show Visibility</strong> - Discover keywords you rank for organically</li><li><strong>Keyword Tracker</strong> - Alternative view focused on individual keyword history</li></ul><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Show Rankings is available on paid plans. Free users see a limited preview with sample keywords.</p><p><strong>Related Features</strong>: Use <a href="/features/keyword-strategy.html">Keyword Strategy</a> to build your keyword plan, <a href="/features/show-visibility.html">Show Visibility</a> to discover organic rankings, and <a href="/features/episode-rankings.html">Episode Rankings</a> for episode-level tracking.</p>',21))])}const f=t(h,[["render",d]]);export{w as __pageData,f as default};
